const baseY = H - 150;

// Record colors
const colors = ['#e6e6e6', '#f5f5f5', '#ffffff', '#f0f0f0', '#d0d0d0', '#b0b0b0'];

// Draw each record
for (let i = 0; i < 5; i++) {
    const y = baseY - i * 30;
    const radius = recordRadius - i * 10;

    // Record outer circle
    ctx.fillStyle = colors[i % 4];
    ctx.beginPath();
    ctx.arc(centerX, y, radius, 0, Math.PI * 2);
    ctx.fill();

    // Record inner circle
    ctx.fillStyle = colors[(i + 1) % 4];
    ctx.beginPath();
    ctx.arc(centerX, y, radius - 20, 0, Math.PI * 2);
    ctx.fill();

    // Record center label
    ctx.fillStyle = '#2d2d2d';
    ctx.beginPath();
    ctx.arc(centerX, y, 20, 0, Math.PI * 2);
    ctx.fill();

    // Record grooves
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    for (let j = 0; j < 12; j++) {
        const angle = (j / 12) * Math.PI * 2;
        const x1 = centerX + Math.cos(angle) * (radius - 10);
        const y1 = y + Math.sin(angle) * (radius - 10);
        const x2 = centerX + Math.cos(angle) * (radius - 30);
        const y2 = y + Math.sin(angle) * (radius - 30);
        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.stroke();
    }
}

