];

// Draw circles with different shades
for (let i = 0; i < 6; i++) {
  const radius = maxRadius - i * 20;
  const context = ctx.createRadialGradient(
    centerX, centerY,
    radius - 10, centerX, centerY,
    radius + 10
  );

  const shade = 0.8 - i * 0.1;
  context.addColorStop(0, colors[i] + ` ${shade * 100}%`);
  context.addColorStop(1, colors[i]);

  ctx.fillStyle = context;
  ctx.beginPath();
  ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
  ctx.fill();
}

// Draw radial patterns
ctx.strokeStyle = '#FFFFFF';
ctx.lineWidth = 2;
for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const startX = centerX + Math.cos(angle) * (maxRadius - 10);
  const startY = centerY + Math.sin(angle) * (maxRadius - 10);
  const endX = centerX + Math.cos(angle) * maxRadius;
  const endY = centerY + Math.sin(angle) * maxRadius;

  ctx.beginPath();
  ctx.moveTo(startX, startY);
  ctx.lineTo(endX, endY);
  ctx.stroke();
}

