// Draw spiral with cool tones
function drawSpiral(x, y, len, angle, depth) {
    if (depth > 0) {
        // Draw line segment
        ctx.fillStyle = C4;
        ctx.globalAlpha = 0.8 - depth * 0.1;
        ctx.fillRect(x, y, len, 2);

        // Recursive draw for spiral arms
        drawSpiral(x + Math.cos(angle) * len, 
                   y + Math.sin(angle) * len, 
                   len * 0.7, 
                   angle + 0.3, 
                   depth - 1);
    }
}

